cd /Users/taha/Documents/portfolio.me/runs/sadeqi-me/prototypes && python3 - <<'PYEOF'
path = "04-photo-treatment.html"
with open(path, encoding="utf-8") as f:
    s = f.read()

old = """  button{
    font-family:'IBM Plex Mono', monospace;
    font-size:12px;
    letter-spacing:.03em;
    background:var(--raised);
    color:var(--ink);
    border:1px solid #2B3B35;
    padding:9px 14px;
    border-radius:3px;
    cursor:pointer;
  }"""
new = """  button{
    font-family:'IBM Plex Mono', monospace;
    font-size:12px;
    letter-spacing:.03em;
    background:var(--raised);
    color:var(--ink);
    border:1px solid #2B3B35;
    padding:9px 14px;
    border-radius:3px;
    cursor:pointer;
    max-width:100%;
    white-space:normal;
    text-align:left;
    flex:1 1 auto;
    min-width:0;
  }"""
assert old in s
s = s.replace(old, new)
with open(path, "w", encoding="utf-8") as f:
    f.write(s)
print("ok")
PYEOF

